import { describe, test, expect } from 'bun:test';
import { sha256 } from './sha256.js';
import { bitArray } from '../utils/bitArray.js';
import { utf8 } from '../../io/codec/utf8.js';
import { hex } from '../../io/codec/hex.js';

const _ba = bitArray.factory();
const _utf8 = utf8.factory();
const _hex = hex.factory();
const _sha = sha256.factory(_ba, _utf8);

const toHex = (ba) => _hex.fromBytes(_ba.ba_to_ui8(ba));
const hashBytes = (ui8) => toHex(_sha.hash(_ba.ui8_to_ba(ui8)));

describe('sha256 module', () => {

    test('module metadata', () => {
        expect(sha256.name).toBe('sha256');
        expect(sha256.dependencies).toEqual(['bitArray', 'utf8']);
    });

    describe('hash (one-shot) - FIPS 180-4 known answers', () => {
        test('empty string -> e3b0c44...', () => {
            expect(toHex(_sha.hash('')))
                .toBe('e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855');
        });

        test('"abc" -> ba7816bf... (FIPS-180 App. B vector 1)', () => {
            expect(toHex(_sha.hash('abc')))
                .toBe('ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad');
        });

        test('FIPS-180 App. B vector 2 (448-bit message)', () => {
            const msg = 'abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq';
            expect(toHex(_sha.hash(msg)))
                .toBe('248d6a61d20638b8e5c026930c3e6039a33ce45964ff2167f6ecedd419db06c1');
        });

        test('FIPS-180 App. B vector 3 (1,000,000 x "a")', () => {
            const msg = 'a'.repeat(1_000_000);
            expect(toHex(_sha.hash(msg)))
                .toBe('cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0');
        });
    });

    describe('streaming (update / finalize)', () => {
        test('chunked update matches one-shot hash', () => {
            const oneShot = toHex(_sha.hash('abcdefghijklmnop'));
            const h = new _sha.fn();
            h.update('abcd');
            h.update('efgh');
            h.update('ijkl');
            h.update('mnop');
            expect(toHex(h.finalize())).toBe(oneShot);
        });

        test('clone via constructor preserves state', () => {
            const a = new _sha.fn();
            a.update('abc');
            const b = new _sha.fn(a);
            expect(toHex(a.finalize())).toBe(toHex(b.finalize()));
        });

        test('reset returns instance to empty state', () => {
            const h = new _sha.fn();
            h.update('garbage');
            h.finalize();
            h.reset();
            h.update('abc');
            expect(toHex(h.finalize()))
                .toBe('ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad');
        });
    });
});

