describe('sha256 - ACVP SHA2-256-1.0', () => {

    describe('AFT vectors (testGroup 1, sub-sampled)', () => {
        test.each(SHA256_AFT)('tcId=$tc (len=$len bits)', (v) => {
            const msg = _hex.toBytes(v.msg);
            // All AFT lens are byte-aligned, so msg.length === v.len/8.
            expect(msg.length * 8).toBe(v.len);
            expect(hashBytes(msg)).toBe(v.md.toLowerCase());
        });
    });

    describe('MCT (testGroup 2, alternate)', () => {
        test('100 outer iterations match resultsArray byte-exact', () => {
            const seedBytes = _hex.toBytes(SHA256_MCT_SEED_HEX);
            const seedLenBytes = SHA256_MCT_SEED_LEN / 8;
            expect(seedBytes.length).toBe(seedLenBytes);

            // Helpers operating on Uint8Array (all lengths are byte-aligned
            // here: SEED=436 B, MD=32 B, A||B||C=3*32=96 B < 436 -> padded
            // back to 436 B by appending zeros; first iter has A=SEED so
            // leftmost-3488 of A||B||C trims back to SEED bytes).
            const concat = (...arrs) => {
                let n = 0;
                for (const a of arrs) n += a.length;
                const out = new Uint8Array(n);
                let o = 0;
                for (const a of arrs) { out.set(a, o); o += a.length; }
                return out;
            };
            const trimOrPad = (buf, targetLen) => {
                if (buf.length === targetLen) return buf;
                if (buf.length > targetLen) return buf.subarray(0, targetLen);
                const out = new Uint8Array(targetLen);
                out.set(buf, 0);
                return out;
            };

            let SEED = seedBytes;
            for (let j = 0; j < 100; j++) {
                let A = SEED, B = SEED, C = SEED;
                for (let i = 0; i < 1000; i++) {
                    let MSG = concat(A, B, C);
                    MSG = trimOrPad(MSG, seedLenBytes);
                    const MD = _ba.ba_to_ui8(_sha.hash(_ba.ui8_to_ba(MSG)));
                    A = B; B = C; C = MD;
                }
                SEED = C; // C === MD of last inner iter
                const got = _hex.fromBytes(SEED);
                expect(got).toBe(SHA256_MCT_EXPECTED[j].toLowerCase());
            }
        }, 60_000);
    });

    // ── Iteration H1 - Large Data Test (LDT, ACVP-SHA2-256-1.0 tg=3) ────────
    //
    // FIPS 180-4 §5.1.1 fixes the message-length counter at 64 bits ; LDT
    // exercises this counter near multi-GiB inputs to detect off-by-one or
    // overflow bugs. The smallest LDT vector hashes 1 GiB of a repeating
    // 8-byte pattern. Even at SJCL throughput (~50 MB/s pure JS) this takes
    // ~20 s ; gated behind `CRYPTO_FULL=1` to keep the default suite snappy.
    const RUN_LDT = process.env.CRYPTO_FULL === '1';
    (RUN_LDT ? describe : describe.skip)('ACVP-SHA2-256-1.0 LDT (1 GiB) - CRYPTO_FULL only', () => {
        test('tcId=514 - 1 GiB of "12735c605f3d270c" repeating', () => {
            const content = _hex.toBytes('12735c605f3d270c'); // 8 bytes
            const fullLengthBits = 8589934592; // 1 GiB
            const fullLengthBytes = fullLengthBits / 8;
            // Build a 1 MiB chunk of the repeating pattern.
            const CHUNK = 1024 * 1024;
            const chunk = new Uint8Array(CHUNK);
            for (let i = 0; i < CHUNK; i += content.length) chunk.set(content, i);
            const chunkBa = _ba.ui8_to_ba(chunk);
            const h = new _sha.fn();
            const iter = fullLengthBytes / CHUNK;
            for (let i = 0; i < iter; i++) h.update(chunkBa);
            expect(toHex(h.finalize())).toBe(
                '171cbe0fef605ae836e05a778cde031e8d475d2f117d121065543abc89cc76b7'
            );
        }, 5 * 60 * 1000);  // 5 min upper bound
    });

});
